contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run will attempt to call getTokens() on c, possibly sending Ether.
    // params: amount of wei to send (value) and a precomputed expected valueBefore (unused here),
    // but main inputs are amount wei to forward and a dummy uint to vary inputs.
    function run(uint256 weiToSend, uint256 dummy) public payable {
        require(address(this).balance >= weiToSend);

        // Observe pre-state via public getters
        uint256 totalDistributedBefore = c.totalDistributed();
        uint256 callerBalanceBefore = c.balanceOf(address(this));
        bool blacklistBefore = c.blacklist(address(this));

        // Call getTokens with provided value, catch revert
        bool reverted;
        try c.getTokens{value: weiToSend}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 totalDistributedAfter = c.totalDistributed();
        uint256 callerBalanceAfter = c.balanceOf(address(this));
        bool blacklistAfter = c.blacklist(address(this));

        // If the call did not revert then: (1) caller became blacklisted (true),
        // (2) caller balance increased by exactly the increase in totalDistributed,
        // which equals the distributed amount to this caller, and that amount is non-negative.
        // We express this as: not reverted implies blacklistAfter is true AND
        // (callerBalanceAfter - callerBalanceBefore) == (totalDistributedAfter - totalDistributedBefore)
        // Use a safe comparison without underflow by checking >= then equality via subtraction on uint256.
        if (!reverted) {
            // Ensure increases are not underflows
            assert(blacklistAfter == true && callerBalanceAfter >= callerBalanceBefore && totalDistributedAfter >= totalDistributedBefore && (callerBalanceAfter - callerBalanceBefore) == (totalDistributedAfter - totalDistributedBefore));
        } else {
            // If reverted, produce a general non-trivial assertion relating observed values: nothing changed.
            // For reverted case, the implementation should not have modified state, so require that totals and balances are equal to before.
            assert(totalDistributedAfter == totalDistributedBefore && callerBalanceAfter == callerBalanceBefore && blacklistAfter == blacklistBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that performs the test. Send wei via weiToSend.
    function run(uint256 weiToSend) public payable {
        require(address(this).balance >= weiToSend);

        // Observe before-state
        uint256 totalDistributedBefore = c.totalDistributed();
        uint256 balBefore = c.balanceOf(address(this));
        bool blackBefore = c.blacklist(address(this));

        // Attempt the state-changing call and record whether it reverted
        bool reverted;
        try c.getTokens{value: weiToSend}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        uint256 totalDistributedAfter = c.totalDistributed();
        uint256 balAfter = c.balanceOf(address(this));
        bool blackAfter = c.blacklist(address(this));

        // Single general assertion covering both reverted and non-reverted cases.
        // If not reverted: blackAfter must be true, and balance increase equals totalDistributed increase.
        // If reverted: none of the three observed values changed.
        assert(
            (!reverted && blackAfter == true && balAfter >= balBefore && totalDistributedAfter >= totalDistributedBefore && (balAfter - balBefore) == (totalDistributedAfter - totalDistributedBefore))
            ||
            (reverted && totalDistributedAfter == totalDistributedBefore && balAfter == balBefore && blackAfter == blackBefore)
        );
    }

    receive() external payable {}
