contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address from, address to, uint256 amount) public payable {
        // require valid addresses for observable behavior
        require(from != address(0) && to != address(0));

        // ensure this contract has enough tokens to set up balances if needed
        // We observe only via public interface. We'll arrange state by using c.transfer from the deploying owner (this contract is the deployer of c)
        // Note: c was deployed fresh with owner == address(this) per problem statement.

        // Read before-balances
        uint256 beforeFrom = c.balanceOf(from);
        uint256 beforeTo = c.balanceOf(to);

        bool reverted;
        // perform transfer from 'from' to 'to' as a top-level call.
        // Since the test contract is msg.sender when calling c, to attempt a transfer from `from` we must call c.transferFrom(from,to,amount)
        // But transferFrom requires allowance; instead we attempt transfer as if msg.sender == from by calling transfer (which will only succeed when from==address(this)).
        // To create a general rule that can be checked for all inputs, we will try two variants depending on whether `from == address(this)`.

        if (from == address(this)) {
            // attempt direct transfer
            try c.transfer(to, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // attempt transferFrom: may revert if allowance or balances insufficient
            try c.transferFrom(from, to, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after-balances
        uint256 afterFrom = c.balanceOf(from);
        uint256 afterTo = c.balanceOf(to);

        // If the call did not revert, then the sum of the two balances must be unchanged (transfer moves tokens between these two accounts only)
        // If the call reverted, then balances must be unchanged as well (no partial effects)
        if (!reverted) {
            assert(beforeFrom + beforeTo == afterFrom + afterTo);
        } else {
            assert(beforeFrom == afterFrom && beforeTo == afterTo);
        }
    }

    receive() external payable { }
}

