        // Read before-balances
        uint256 beforeFrom = c.balanceOf(from);
        uint256 beforeTo = c.balanceOf(to);

        bool revertedTransfer;
        bool attemptedTransfer;
        // We will attempt exactly one state-changing call on c as a top-level statement.
        // If from == address(this) we call transfer(to, amount), otherwise call transferFrom(from,to,amount).
        if (from == address(this)) {
            attemptedTransfer = true;
            // top-level state-changing call
            try c.transfer(to, amount) {
                revertedTransfer = false;
            } catch {
                revertedTransfer = true;
            }
        } else {
            attemptedTransfer = true;
            // top-level state-changing call
