        uint256 afterTo = c.balanceOf(to);

        // Single assert expressing the general invariant depending on revert flag
        // If we attempted the call and it reverted then balances unchanged; if it succeeded then sum preserved.
        assert(!attemptedTransfer || (revertedTransfer ? (beforeFrom == afterFrom && beforeTo == afterTo) : (beforeFrom + beforeTo == afterFrom + afterTo)));
    }

    receive() external payable { }
