contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = address(this); }

    // single public test function
    function run(address caller, bool useAsOwner) public payable {
        require(caller != address(0)); // ensure a valid caller address

        // We need to possibly transfer ownership first so that either this contract (deployer)
        // or `caller` is the owner when calling finishDistribution.
        // The test environment: InvMutTest deployed C, so c.owner == address(this) initially.
        // If useAsOwner == true, ensure owner is this contract; else transfer ownership to `caller`.

        if (!useAsOwner) {
            // transfer ownership to caller so that caller becomes owner and this contract is not owner
            // transferOwnership is onlyOwner, so this (current owner) can call it.
            c.transferOwnership(caller);
        }

        // Read distributionFinished before the call
        bool before = c.distributionFinished();

        // Try calling finishDistribution via the chosen caller address.
        // We must simulate external calls from either this contract (owner) or from caller.
        bool reverted;
        if (useAsOwner) {
            // call as owner: this contract
            try c.finishDistribution() returns (bool res) {
                reverted = false;
                // require the returned value to be res for later observation
            } catch {
                reverted = true;
            }
        } else {
            // call as non-owner: we need to invoke finishDistribution from the `caller` address.
            // Achieve this by making the contract call a short-circuited external call using address(c).
            // We perform a low-level call encoding the selector for finishDistribution.
            // Selector for finishDistribution() is bytes4(keccak256("finishDistribution()"))
            bytes memory payload = abi.encodeWithSelector(bytes4(keccak256("finishDistribution()")));
            (bool ok, ) = address(c).call(payload);
            reverted = !ok;
        }

        // Read distributionFinished after the call
        bool after = c.distributionFinished();

        // General rule to assert:
        // - If the call was made by the owner (useAsOwner==true) then it must NOT revert and after==true.
        // - If the call was made by non-owner (useAsOwner==false) then it must revert and after equals before (no change).
        assert( (useAsOwner && !reverted && after) || (!useAsOwner && reverted && after == before) );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: transferOwnershipToOther=true means we will transfer ownership to `other` so that this contract is NOT owner
    // otherwise this contract remains owner. We use low-level call to simulate a non-owner invoking finishDistribution().
    function run(address other, bool transferOwnershipToOther) public payable {
        require(other != address(0));

        // Ensure initial owner state: when C was deployed, owner == address(this).
        // If transferOwnershipToOther is true, transfer ownership to `other` so that this contract is not the owner anymore.
        if (transferOwnershipToOther) {
            // this call is onlyOwner and should succeed because this contract is initial owner
            c.transferOwnership(other);
        }

        // Read distributionFinished before
        bool before = c.distributionFinished();

        // Now attempt to call finishDistribution() as the owner or as non-owner.
        // If transferOwnershipToOther == false: this contract is owner and will call c.finishDistribution() directly.
        // If transferOwnershipToOther == true: this contract is not owner; perform low-level call from this contract to simulate a NON-owner call.
        bool reverted;
        if (!transferOwnershipToOther) {
            // call as owner
            try c.finishDistribution() returns (bool res) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call as non-owner via low-level call
            bytes memory payload = abi.encodeWithSelector(bytes4(keccak256("finishDistribution()")));
            (bool ok, ) = address(c).call(payload);
            reverted = !ok;
        }

        // Read distributionFinished after
        bool after = c.distributionFinished();

        // Assert the general rule:
        // - If call was by owner (transferOwnershipToOther == false) then it must not revert and after == true.
        // - If call was by non-owner (transferOwnershipToOther == true) then it must revert and after == before.
        assert((!transferOwnershipToOther && !reverted && after) || (transferOwnershipToOther && reverted && after == before));
    }

    receive() external payable { }
}

contract InvMutTest {
