    // single public test function
    // If transferToOther==true this contract transfers ownership away before attempting finishDistribution
    function run(address other, bool transferToOther) public payable {
        require(other != address(0));

        // read distributionFinished before any actions
        bool before = c.distributionFinished();

        // optionally transfer ownership away so this contract is not the owner
        if (transferToOther) {
            c.transferOwnership(other);
        }

        // try to call finishDistribution and record whether it reverted
        bool reverted;
        // If this contract is still owner, call via ABI (will execute as owner)
        // If not owner, use low-level call to capture revert as boolean as well
        if (!transferToOther) {
            try c.finishDistribution() returns (bool res) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            bytes memory payload = abi.encodeWithSelector(bytes4(keccak256("finishDistribution()")));
            (bool ok, ) = address(c).call(payload);
            reverted = !ok;
        }

        // read distributionFinished after
        bool afterDist = c.distributionFinished();

        // Assertion: if we remained owner, call must not revert and distributionFinished becomes true;
        // if we transferred ownership away, the call must revert and distributionFinished stays equal to before.
        assert((!transferToOther && !reverted && afterDist) || (transferToOther && reverted && afterDist == before));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: candidate newOwner and a flag indicating whether this contract should first renounce ownership by transferring to candidate2
    function run(address newOwner, address candidate2, bool preTransfer) public payable {
        require(newOwner != address(0)); // we will test valid newOwner cases
        // read current owner via public variable 'owner' is not public in C; but we can observe behavior through transferOwnership calls

        // Optionally transfer ownership away from this contract to candidate2 before testing
        if (preTransfer) {
            // must be a top-level state-changing call on c
            c.transferOwnership(candidate2);
        }

        // Attempt to transfer ownership to newOwner and detect whether it reverted
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, try to transfer ownership again to the zero address via this contract to observe whether this contract is currently owner.
        // This second attempt will succeed (i.e., not revert) exactly when this contract is the owner after the first transfer; but transferOwnership ignores zero address so it will leave owner unchanged if non-zero check fails.
        bool secondReverted;
        try c.transferOwnership(address(0)) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule expressed as an assertion combining observed reverts:
        // If we were still owner when calling transferOwnership(newOwner) then the call does not revert and owner becomes newOwner — hence a subsequent attempt by this contract to transfer to zero will revert (since this contract is no longer owner).
        // If we were not owner when calling transferOwnership(newOwner) then the call reverts and this contract remains not-owner, so the subsequent attempt also reverts.
        // Therefore: either (first call succeeded and second call reverts) or (first call reverted and second call reverted).
        // This encodes that only the owner could successfully change ownership and that after a successful ownership transfer this contract is no longer owner.
        assert((!reverted && secondReverted) || (reverted && secondReverted));
    }

    receive() external payable { }
}
